/**
 * @brief get flash information
 *
 * @param[out] info: the description of the flash
 *
 * @note This API is used to get description of storage.
 *
 * @return OPRT_OK on success. Others on error, please refer to tuya_error_code.h
 */
OPERATE_RET tkl_flash_get_one_type_info(TUYA_FLASH_TYPE_E type, TUYA_FLASH_BASE_INFO_T *info)
{
    // --- BEGIN: user implements ---
    if (type >= TUYA_FLASH_TYPE_MAX || info == NULL) {
        return OPRT_INVALID_PARM;
    }
    if (!gd32h77x_cnvm_is_initialized()) {
        return OPRT_RESOURCE_NOT_READY;
    }

    uint32_t start = 0U;
    uint32_t size = 0U;
    uint32_t block_size = gd32h77x_layout_partitions[GD32H77X_LAYOUT_PART_TUYA].erase_bytes;
    switch (type) {
    case TUYA_FLASH_TYPE_UF:
        start = GD32H77X_LAYOUT_TUYA_LOGICAL_BASE;
        size = TUYA_FLASH_UF_SIZE;
        if (size > GD32H77X_LAYOUT_TUYA_SIZE_BYTES) {
            size = GD32H77X_LAYOUT_TUYA_SIZE_BYTES;
        }
        break;
    case TUYA_FLASH_TYPE_KV_DATA:
        start = GD32H77X_LAYOUT_TUYA_LOGICAL_BASE + TUYA_FLASH_KV_DATA_OFFSET;
        size = TUYA_FLASH_KV_DATA_SIZE;
        break;
    case TUYA_FLASH_TYPE_KV_KEY:
        start = GD32H77X_LAYOUT_TUYA_LOGICAL_BASE + TUYA_FLASH_KV_KEY_OFFSET;
        size = TUYA_FLASH_KV_KEY_SIZE;
        break;
    case TUYA_FLASH_TYPE_KV_SWAP:
        start = GD32H77X_LAYOUT_TUYA_LOGICAL_BASE + TUYA_FLASH_KV_SWAP_OFFSET;
        size = TUYA_FLASH_KV_SWAP_SIZE;
        break;
    case TUYA_FLASH_TYPE_KV_PROTECT:
        start = GD32H77X_LAYOUT_TUYA_LOGICAL_BASE + TUYA_FLASH_KV_PROTECT_OFFSET;
        size = TUYA_FLASH_KV_PROTECT_SIZE;
        break;
    case TUYA_FLASH_TYPE_USER0:
        start = GD32H77X_LAYOUT_TUYA_LOGICAL_BASE + TUYA_FLASH_USER0_OFFSET;
        size = TUYA_FLASH_USER0_SIZE;
        break;
    case TUYA_FLASH_TYPE_APP:
    case TUYA_FLASH_TYPE_APP_BIN:
        start = GD32H77X_PRIMARY_BASE;
        size = GD32H77X_PRIMARY_SIZE;
        block_size = UINT32_C(0x00010000);
        break;
    case TUYA_FLASH_TYPE_OTA:
        start = GD32H77X_STAGING_BASE;
        size = GD32H77X_STAGING_SIZE;
        block_size = UINT32_C(0x00001000);
        break;
    case TUYA_FLASH_TYPE_INFO:
        start = GD32H77X_METADATA_BASE;
        size = GD32H77X_METADATA_SIZE;
        block_size = UINT32_C(0x00001000);
        break;
    default:
        return OPRT_NOT_SUPPORTED;
    }

    const gd32h77x_flash_op_t ops[] = {
        GD32H77X_FLASH_OP_READ, GD32H77X_FLASH_OP_WRITE, GD32H77X_FLASH_OP_ERASE,
    };
    for (size_t i = 0U; i < sizeof(ops) / sizeof(ops[0]); ++i) {
        OPERATE_RET result = gd32h77x_flash_access_preflight(start, size, ops[i]);
        if (result != OPRT_OK) {
            return result;
        }
    }

    memset(info, 0, sizeof(*info));
    info->partition_num = 1U;
    info->partition[0].start_addr = start;
    info->partition[0].size = size;
    info->partition[0].block_size = block_size;
    return OPRT_OK;
    // --- END: user implements ---
}

